//! Owner HTTP feedback removal; no native/provider operation is started.
use std::{sync::{Arc,Mutex},path::Path};
use serde_json::json;
#[test]fn paired_owner_can_delete_feedback_without_a_native_connection(){
 let base=Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap().join("runtime");std::fs::create_dir_all(&base).unwrap();let dir=tempfile::tempdir_in(base).unwrap();let store=Arc::new(crate::RouterStore::open_at(dir.path().join("router.db")).unwrap());let root=dir.path().to_string_lossy().to_string();
 store.enable_codex_watch("exact-delete","fixture",&root,&router_core::store::codex_watch::WatchSnapshot{state:"IDLE".into(),turn_id:None,item_id:None,text:String::new()}).unwrap();let id=uuid::Uuid::new_v4().to_string();let r=router_core::store::watch_reply::WatchReply{id:id.clone(),thread_id:"exact-delete".into(),cwd:root,generation:store.codex_chat_context("exact-delete").unwrap().generation,source_sequence:None,expected_turn_id:None,mode:"SEND".into(),text:"body to remove".into(),options:json!({"attachments":[]}),payload_hash:String::new(),status:String::new(),turn_id:None,error_code:None,created_at:0,updated_at:0};store.prepare_watch_reply(&r).unwrap();store.claim_watch_reply(&id).unwrap();store.finish_watch_reply(&id,"UNKNOWN",None,None).unwrap();
 let core=crate::host_application::RouterCore{store:store.clone(),session:Arc::new(Mutex::new(Default::default())),chatgpt:Default::default(),completed_chatgpt_responses:Default::default()};let auth=Arc::new(crate::web_auth::WebAuth::open(None).unwrap());let rt=tokio::runtime::Runtime::new().unwrap();let host=crate::HostRuntime::default();let config=crate::mobile_http::MobileHttpConfig{port:0,allowed_host:"remove.fixture.invalid".into(),allowed_origin:"https://remove.fixture.invalid".into(),access_issuer:"https://unused.invalid".into(),access_audience:"unused".into(),access_jwks_url:"https://unused.invalid/keys".into(),static_dir:dir.path().into()};let http=rt.block_on(crate::mobile_http::start_with_web_auth(core,config,host,auth.clone())).unwrap();let url=format!("http://{}",http.address);let client=reqwest::blocking::Client::builder().no_proxy().build().unwrap();let payload=json!({"action":"DISCARD_REPLY","threadId":"exact-delete","id":id});
 assert_eq!(client.post(format!("{url}/v1/mobile/codex-watches/chat")).header("host","remove.fixture.invalid").header("origin","https://remove.fixture.invalid").json(&payload).send().unwrap().status(),401);assert_eq!(store.watch_reply(&id).unwrap().unwrap().status,"UNKNOWN");
 let code=auth.issue().unwrap();let paired=client.post(format!("{url}/v1/mobile/auth/pair")).header("host","remove.fixture.invalid").header("origin","https://remove.fixture.invalid").json(&json!({"code":code.code,"deviceName":"disposable deletion test"})).send().unwrap();assert_eq!(paired.status(),200);let cookie=paired.headers()["set-cookie"].to_str().unwrap().split(';').next().unwrap();
 let response=client.post(format!("{url}/v1/mobile/codex-watches/chat")).header("host","remove.fixture.invalid").header("origin","https://remove.fixture.invalid").header("cookie",cookie).json(&payload).send().unwrap();assert_eq!(response.status(),200);assert_eq!(response.json::<serde_json::Value>().unwrap()["removed"],true);assert!(store.watch_replies("exact-delete").unwrap().is_empty());let old=store.watch_reply(&id).unwrap().unwrap();assert!(old.text.is_empty());assert_eq!(old.status,"ACKNOWLEDGED");assert_eq!(old.error_code.as_deref(),Some("OWNER_DISCARDED_UNCONFIRMED_REPLY"));
 assert!(!crate::assistant_mcp::tools_for_scope("INSTANCE").to_string().contains("DISCARD_REPLY"));
}
